INSERT INTO `v1_950d97f211b0a8ab6d7ab0f4eab3584cf3a45a99fe79cd926d066071543e4299` VALUES (0, 101611, 11, 8, 312005, 0, "見て見てミサキっち！\nあそこの料理すっごく美味しそう！", 0, 0.5, 312, 0);
INSERT INTO `v1_950d97f211b0a8ab6d7ab0f4eab3584cf3a45a99fe79cd926d066071543e4299` VALUES ("", 101611, 3, 1, 312006, "", "nop_talk_surprise_kira", 0.2, "", 312, "");
